import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.launch

class MyViewModel : ViewModel() {
    private val repository = FirebaseRepository()
    private var _entity = mutableStateOf<MyEntity?>(null)
    val entity: MyEntity? get() = _entity.value

    init {
        loadEntityFromFirebase()
    }

    private fun loadEntityFromFirebase() {
        viewModelScope.launch {
            val result = repository.getEntityFromFirebase()
            _entity.value = result
        }
    }
}
